    )

    private val GZIPPED_PHRASES_B64_PARTS: Array<String> = arrayOf(
        "",
        "",
        "",
        "",
    )

    private val phraseMap: Map<String, String> by lazy {
        val fullB64 = GZIPPED_PHRASES_B64_PARTS.joinToString("")
        val compressedBytes = Base64.getDecoder().decode(fullB64)
        val map = HashMap<String, String>()
        GZIPInputStream(ByteArrayInputStream(compressedBytes)).use { gzip ->
            InputStreamReader(gzip, StandardCharsets.UTF_8).buffered().useLines { lines ->
                for (line in lines) {
                    val tabIdx = line.indexOf('\t')
                    if (tabIdx > 0) {
                        val key = line.substring(0, tabIdx)
                        val value = line.substring(tabIdx + 1)
                        map[key] = value
                    }
                }
            }
        }
        map
    }

    /**
     * Converts simplified Chinese text to Taiwan Standard Traditional Chinese (zh-TW).
     * Non-Chinese characters and characters already in traditional form are preserved.
     */
    fun convert(text: String): String {
        if (text.isEmpty()) return text
        val stage1 = StringBuilder(text.length)
        val phrases = phraseMap
        var i = 0
        val n = text.length

        while (i < n) {
            var matched = false
            val maxLen = minOf(MAX_PHRASE_LENGTH, n - i)
            for (len in maxLen downTo 2) {
                val sub = text.substring(i, i + len)
                val targetPhrase = phrases[sub]
                if (targetPhrase != null) {
                    stage1.append(targetPhrase)
                    i += len
                    matched = true
                    break
                }
            }
            if (!matched) {
                // Check supplementary single char or BMP char
                val ch = text[i]
                val index = Arrays.binarySearch(SIMPLIFIED_CHARS, ch)
                if (index >= 0) {
                    stage1.append(TRADITIONAL_TARGETS[index])
                } else {
                    // Check if supplementary (2 chars) in phraseMap
                    if (i + 2 <= n && phrases.containsKey(text.substring(i, i + 2))) {
                        stage1.append(phrases[text.substring(i, i + 2)])
                        i++
                    } else {
                        stage1.append(ch)
                    }
                }
                i++
            }
        }

        // Stage 2: Taiwan Standard variants (e.g. 裏 -> 裡, 麪 -> 麵)
        val intermediate = stage1.toString()
        val stage2 = StringBuilder(intermediate.length)
        var j = 0
        val m = intermediate.length

        while (j < m) {
            var phraseMatched = false
            for ((pSrc, pTgt) in TW_VARIANT_PHRASES) {
                if (intermediate.startsWith(pSrc, j)) {
                    stage2.append(pTgt)
                    j += pSrc.length
                    phraseMatched = true
                    break
                }
            }
            if (!phraseMatched) {
                val ch = intermediate[j]
                val varIndex = Arrays.binarySearch(TW_VARIANT_CHARS_SRC, ch)
                if (varIndex >= 0) {
                    stage2.append(TW_VARIANT_CHARS_TGT[varIndex])
                } else {
                    stage2.append(ch)
                }
                j++
            }
        }

        return stage2.toString()
    }
